using JamunaBank.Procurement.API.Constants;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Services.Interfaces;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace JamunaBank.Procurement.API.Controllers;
[ApiController,Authorize(Policy=AuthorizationPolicyNames.ProcurementPrint),Route("api/procurement/requisitions")]
public sealed class RequisitionFormController(IRequisitionFormService service):ControllerBase
{[HttpGet("ready")]public async Task<ActionResult<ApiResponse<ReadyRequisitionPageDto>>>Ready([FromQuery]string?search,[FromQuery]string?requisitionType,[FromQuery]long?concernDivisionId,[FromQuery]DateOnly?fromDate,[FromQuery]DateOnly?toDate,[FromQuery]int pageNumber=1,[FromQuery]int pageSize=10,CancellationToken ct=default){var x=await service.GetReadyAsync(search,requisitionType,concernDivisionId,fromDate,toDate,pageNumber,pageSize,ct);return Ok(ApiResponse<ReadyRequisitionPageDto>.Ok(x,"Ready for Procurement requisitions loaded.",HttpContext.TraceIdentifier));}[HttpGet("{id:long}/requisition-form")]public async Task<ActionResult<ApiResponse<RequisitionFormDto>>>Form(long id,CancellationToken ct){try{var x=await service.GetFormAsync(id,ct);return x is null?NotFound(ApiResponse<RequisitionFormDto>.Fail("Requisition form was not found.",[],HttpContext.TraceIdentifier)):Ok(ApiResponse<RequisitionFormDto>.Ok(x,"Requisition form generated.",HttpContext.TraceIdentifier));}catch(Exception e)when(e.Message.Contains("not Ready for Procurement",StringComparison.OrdinalIgnoreCase)){return Conflict(ApiResponse<RequisitionFormDto>.Fail("The requisition is not eligible for printing.",[e.Message],HttpContext.TraceIdentifier));}}}
